import json

# Function to find the ownership summary table
def find_ownership_data(data, year):
    for elem in data['document']['elements']:
        if elem.get('type') == 'table':
            content = elem.get('content')
            if content and 'commercial banks' in content.lower():
                if 'Marketable' in content and 'Total' in content:
                    return content
    return None

# Look at different years
for year in ['1978', '1979', '1980', '1981', '1982']:
    filename = f'/app/resources/treasury_bulletin_{year}_05.json'
    try:
        data = json.load(open(filename))
        result = find_ownership_data(data, year)
        if result:
            # Look for the row with "Marketable" and "Total"
            lines = result.split('<tr>')
            for line in lines:
                if 'Marketable' in line and 'Total' in line:
                    print(f"\n=== Year {year} ===")
                    print(line[:2000])
    except Exception as e:
        print(f"Error processing {year}: {e}")
EOF

