python3 << 'EOF'
import json

# Let's be more specific - find the table with column headers showing "commercial banks"
def find_ownership_table(data):
    for elem in data['document']['elements']:
        if elem.get('type') == 'table':
            content = elem.get('content')
            if content:
                # Check for both "commercial banks" and "Marketable"
                if 'commercial banks' in content.lower() and 'Marketable' in content:
                    # Now check the structure - we need the row with just "Marketable"
                    lines = content.split('<tr>')
                    for line in lines:
                        # Look for row that starts with Marketable directly (not a header)
                        if '<td>Marketable</td>' in line:
                            parts = line.split('<td>')
                            # Index 5 should have the commercial banks value
                            val = parts[5].replace('</td>', '').replace(',', '')
                            return int(val)
    return None

# Process all years
years = ['1978', '1979', '1980', '1981', '1982']
results = {}

for year in years:
    filename = f'/app/resources/treasury_bulletin_{year}_05.json'
    data = json.load(open(filename))
    val = find_ownership_table(data)
    print(f"Year {year}: {val}")
    results[year] = val

print("\n=== All Results ===")
for year, value in sorted(results.items()):
    print(f"{year}: {value}")
EOF
